tags.gen_ai.tool.definitions:
[
  {
    "type": "function",
    "name": "list_artifacts",
    "description": "Entdecke die verf\u00FCgbare L1/L2-Umwelt: Artefakttypen, Item-Zahlen und Beispiel-IDs. Rufe es zuerst.",
    "parameters": {
      "type": "object",
      "properties": {}
    }
  },
  {
    "type": "function",
    "name": "search_items",
    "description": "Suche Items per Stichwort \u00FCber alle verf\u00FCgbaren Artefakte. Liefert itemId, Artefakttyp und kurzen Textauszug.",
    "parameters": {
      "type": "object",
      "properties": {
        "query": {
          "type": "string"
        },
        "limit": {
          "type": "integer",
          "default": 20
        }
      },
      "required": [
        "query"
      ]
    }
  },
  {
    "type": "function",
    "name": "get_item",
    "description": "Hole ein einzelnes Umwelt-Item mit Text, Herkunfts-IDs und Artefakttyp per itemId.",
    "parameters": {
      "type": "object",
      "properties": {
        "itemId": {
          "type": "string"
        }
      },
      "required": [
        "itemId"
      ]
    }
  },
  {
    "type": "function",
    "name": "get_source_claims",
    "description": "Drill-down unter ein Umwelt-Item: liefert Ledger-Claims, soweit ein Ledger geladen ist, sonst die Claim-IDs.",
    "parameters": {
      "type": "object",
      "properties": {
        "itemId": {
          "type": "string"
        }
      },
      "required": [
        "itemId"
      ]
    }
  },
  {
